class Solution:
    def lengthOfLongestSubsequence(self, nums: List[int], target: int) -> int:
        NEG = float('-inf')
        dp = [NEG] * (target + 1)
        dp[0] = 0
        for x in nums:
            for s in range(target, x - 1, -1):
                if dp[s - x] != NEG:
                    cand = dp[s - x] + 1
                    if cand > dp[s]:
                        dp[s] = cand
        return dp[target] if dp[target] != NEG else -1
