def gen(draw):
    n = draw(st.integers(1, 10))
    nums = draw(st.lists(st.integers(1, 10), min_size=n, max_size=n))
    target = draw(st.integers(1, 30))
    return f"{json.dumps(nums)}\n{json.dumps(target)}"

def validate(inp):
    try:
        lines = inp.strip().split("\n")
        if len(lines) != 2:
            return False
        nums = json.loads(lines[0])
        target = json.loads(lines[1])
        if not isinstance(nums, list) or not isinstance(target, int) or isinstance(target, bool):
            return False
        if not (1 <= len(nums) <= 1000):
            return False
        if not all(isinstance(x, int) and not isinstance(x, bool) and 1 <= x <= 1000 for x in nums):
            return False
        if not (1 <= target <= 1000):
            return False
        return True
    except Exception:
        return False

def ref(inp):
    lines = inp.strip().split("\n")
    nums = json.loads(lines[0])
    target = json.loads(lines[1])
    n = len(nums)
    best = -1
    # Exhaustive search over all subsets (by index bitmask)
    for mask in range(1, 1 << n):
        total = 0
        cnt = 0
        for i in range(n):
            if mask >> i & 1:
                total += nums[i]
                cnt += 1
        if total == target:
            if cnt > best:
                best = cnt
    return json.dumps(best)
