@st.composite
def gen(draw):
    n = draw(st.integers(1, 10))
    mode = draw(st.integers(0, 4))
    if mode == 0:
        # all equal elements
        v = draw(st.integers(1, 6))
        nums = [v] * n
    elif mode == 1:
        # sorted ascending
        nums = sorted(draw(st.lists(st.integers(1, 12), min_size=n, max_size=n)))
    elif mode == 2:
        # reverse sorted
        nums = sorted(draw(st.lists(st.integers(1, 12), min_size=n, max_size=n)), reverse=True)
    else:
        nums = draw(st.lists(st.integers(1, 12), min_size=n, max_size=n))
    total = sum(nums)
    choice = draw(st.integers(0, 2))
    if choice == 0:
        target = draw(st.integers(1, 40))
    elif choice == 1:
        # target achievable: sum of a random nonempty subset
        mask = draw(st.integers(1, (1 << n) - 1))
        target = sum(nums[i] for i in range(n) if mask >> i & 1)
    else:
        target = max(1, min(1000, total))
    target = min(max(target, 1), 1000)
    return json.dumps(nums) + "\n" + json.dumps(target) + "\n"

